import EditAudiobookModal from '@/components/domain/audiobook/EditAudiobookModal.vue'

const audiobook = {
  id: 1,
  title: 'Sample',
  authors: ['Author'],
  basePath: 'C:\\root\\Some Author\\Some Title',
  monitored: true,
  tags: [],
}

describe('EditAudiobookModal relative path calculation', () => {
  it('shows full path in readonly input by default', async () => {
    const wrapper = mount(EditAudiobookModal, {
      props: {
        isOpen: true,
        audiobook,
      },
      attachTo: document.body,
      global: {
        plugins: [(await import('pinia')).createPinia()],
      },
    })

    // allow async init
    await new Promise((r) => setTimeout(r, 10))

    // Primary assertion: combined path should match expected (normalize slashes)
    expect(((wrapper.vm as unknown).combinedBasePath() || '').replace(/\\/g, '/')).toBe('C:/root/Some Author/Some Title')

    // If the readonly input exists in this environment, also assert its value
    const readonlyInput = wrapper.find('.readonly-input')
    if (readonlyInput.exists()) {
      expect(((readonlyInput.element as HTMLInputElement).value || '').replace(/\\/g, '/')).toBe('C:/root/Some Author/Some Title')
    }
  })

  it('derives relative path from stored basePath when root configured', async () => {
    const wrapper = mount(EditAudiobookModal, {
      props: {
        isOpen: true,
        audiobook,
      },
      attachTo: document.body,
      global: {
        plugins: [(await import('pinia')).createPinia()],
      },
    })

    // allow async init
    await new Promise((r) => setTimeout(r, 10))

    // Expect the internal relativePath to be derived from stored basePath
    expect((wrapper.vm as unknown).formData.relativePath).toBe('Some Author\\Some Title')
  })

  it('normalizes absolute path to relative when Done is clicked', async () => {
    const wrapper = mount(EditAudiobookModal, {
      props: {
        isOpen: true,
        audiobook,
      },
      attachTo: document.body,
      global: {
        plugins: [(await import('pinia')).createPinia()],
      },
    })

    // allow async init
    await new Promise((r) => setTimeout(r, 10))

    // Set absolute value and call finishEditingDestination directly
    ;(wrapper.vm as unknown).formData.relativePath = 'C:\\root\\New Author\\New Title'
    await (wrapper.vm as unknown).finishEditingDestination()

    // After normalization the internal relativePath should be the short relative
    expect((wrapper.vm as unknown).formData.relativePath).toBe('New Author\\New Title')
  })

  it('preserves a user-typed relative path after Done and reopen', async () => {
    const wrapper = mount(EditAudiobookModal, {
      props: {
        isOpen: true,
        audiobook,
      },
      attachTo: document.body,
      global: {
        plugins: [(await import('pinia')).createPinia()],
      },
    })

    // allow async init
    await new Promise((r) => setTimeout(r, 10))

    // Type a relative path and call Done directly
    ;(wrapper.vm as unknown).formData.relativePath = 'My Author\\My Title'
    await (wrapper.vm as unknown).finishEditingDestination()

    // The internal relativePath should remain what the user typed
    expect((wrapper.vm as unknown).formData.relativePath).toBe('My Author\\My Title')
  })

  it('prefills absolute path when switching to Custom path', async () => {
    const wrapper = mount(EditAudiobookModal, {
      props: {
        isOpen: true,
        audiobook,
      },
      attachTo: document.body,
      global: {
        plugins: [(await import('pinia')).createPinia()],
      },
    })

    // allow async init
    await new Promise((r) => setTimeout(r, 10))

    // Simulate switching to Custom path by setting selectedRootId
    ;(wrapper.vm as unknown).selectedRootId = 0
    await nextTick()

    // customRootPath should be prefilled to the full base path (normalize slashes)
    expect(((wrapper.vm as unknown).customRootPath || '').replace(/\\/g, '/')).toBe('C:/root/Some Author/Some Title')
  })

  it('does not duplicate relative part when saving a Custom path', async () => {
    const wrapper = mount(EditAudiobookModal, {
      props: {
        isOpen: true,
        audiobook,
      },
      attachTo: document.body,
      global: {
        plugins: [(await import('pinia')).createPinia()],
      },
    })

    // allow async init
    await new Promise((r) => setTimeout(r, 10))

    // Simulate selecting Custom path directly
    ;(wrapper.vm as unknown).selectedRootId = 0
    ;(wrapper.vm as unknown).customRootPath = (wrapper.vm as unknown).combinedBasePath()
    await nextTick()

    // combinedBasePath should equal the custom path exactly (no duplication)
    const cb = (wrapper.vm as unknown).combinedBasePath()
    const cr = (wrapper.vm as unknown).customRootPath
    expect((cb || '').replace(/\\/g, '/')).toBe((cr || '').replace(/\\/g, '/'))
  })

  it('selects custom path via folder browser and saves exact custom path (no duplication)', async () => {
    const wrapper = mount(EditAudiobookModal, {
      props: {
        isOpen: true,
        audiobook,
      },
      attachTo: document.body,
      global: {
        plugins: [(await import('pinia')).createPinia()],
      },
    })

    // allow async init
    await new Promise((r) => setTimeout(r, 10))

    // Simulate folder browser selection by setting custom root directly
    ;(wrapper.vm as unknown).selectedRootId = 0
    ;(wrapper.vm as unknown).customRootPath = 'C:\\temp\\Isaac Asimov\\Foundation'
    await nextTick()

    // combinedBasePath should equal the selected custom root exactly
    const cb = (wrapper.vm as unknown).combinedBasePath()
    expect(cb.replace(/\\/g, '/')).toBe('C:/temp/Isaac Asimov/Foundation')
  })
})

import { mount } from '@vue/test-utils'
import { nextTick } from 'vue'
import { describe, it, expect } from 'vitest'
import ManualSearchModal from '@/components/domain/search/ManualSearchModal.vue'

type ManualSearchResult = {
  id: string
  title?: string
  downloadType?: string
  resultUrl?: string
  source?: string
  nzbUrl?: string
  sourceLink?: string
  size?: number
  quality?: string
  format?: string
  language?: string
}

type QualityScore = {
  searchResult: ManualSearchResult
  totalScore: number
  scoreBreakdown: Record<string, unknown>
  rejectionReasons: string[]
  isRejected: boolean
  smartScore?: number
  smartScoreBreakdown?: Record<string, unknown>
}

type QualityScoresMap =
  | Map<string, QualityScore>
  | { value?: Map<string, QualityScore>; set?: (k: string, v: QualityScore) => void }
  | Map<string, QualityScore>

describe('ManualSearchModal.vue', () => {
  const stubs = {
    PhMagnifyingGlass: true,
    PhX: true,
    PhSpinner: true,
    PhArrowClockwise: true,
    PhArrowUp: true,
    PhArrowDown: true,
    PhXCircle: true,
    PhDownloadSimple: true,
    PhArrowsDownUp: true,
    // Ensure ScorePopover renders its default slot in tests so the inner badge is present
    ScorePopover: { template: '<div><slot /></div>' },
    Modal: { template: '<div><slot name="header" /><slot /></div>' },
    ModalHeader: { template: '<div><slot /></div>' },
    ModalBody: { template: '<div><slot /></div>' },
  }

  // Helper to set `results` on the component instance in a way that works
  // whether the component exposes a ref (`.value`) or an unwrapped array.
  const setResultsOnVm = (vm: unknown, r: unknown) => {
    if (vm && vm.results && typeof vm.results === 'object' && 'value' in vm.results) {
      vm.results.value = r
    } else if (vm) {
      vm.results = r
    }
  }

  it('uses details page for Usenet title links instead of direct NZB', async () => {
    const wrapper = mount(ManualSearchModal, {
      props: { isOpen: true, audiobook: null },
      global: { stubs },
    })
    const vm = wrapper.vm as unknown as {
      results: ManualSearchResult[]
      qualityScores?: QualityScoresMap
    }

    // Set a usenet-style result where id is an informational URL that should be used for the title link
    // Support both raw arrays and refs (test runner may expose refs differently)
    const setResults = (r: unknown) => {
      if (vm && (vm as unknown).results && typeof (vm as unknown).results === 'object' && 'value' in (vm as unknown).results) {
        ;(vm as unknown).results.value = r
      } else if (vm) {
        ;(vm as unknown).results = r
      }
    }

    setResultsOnVm(vm, [
      {
        id: 'https://indexer/info/123',
        title: 'Test Usenet',
        downloadType: 'Usenet',
        resultUrl: '',
        sourceLink: 'https://indexer/info/123',
        nzbUrl: 'https://indexer/download/123.nzb',
        source: 'altHUB',
        size: 123,
      },
    ])

    await nextTick()

    // Debug: show rendered HTML to investigate missing anchor

    console.log(wrapper.html())
    const anchor = wrapper.find('a.title-text')
    expect(anchor.exists()).toBe(true)
    expect(anchor.attributes('href')).toBe('https://indexer/info/123')
  })

  it('does not show language badge when language is Unknown', async () => {
    const wrapper = mount(ManualSearchModal, {
      props: { isOpen: true, audiobook: null },
      global: { stubs },
    })
    const vm = wrapper.vm as unknown as {
      results: ManualSearchResult[]
      qualityScores?: QualityScoresMap
    }

    setResultsOnVm(vm, [
      {
        id: 'u2',
        title: 'Lang Test',
        language: 'Unknown',
        downloadType: 'Usenet',
        resultUrl: 'https://indexer/info/2',
        source: 'alt',
        size: 0,
      },
    ])

    await nextTick()

    const langBadge = wrapper.find('.language-badge')
    expect(langBadge.exists()).toBe(false)
  })

  it('does not show duplicate format fallback when format equals quality', async () => {
    const wrapper = mount(ManualSearchModal, {
      props: { isOpen: true, audiobook: null },
      global: { stubs },
    })
    const vm = wrapper.vm as unknown as {
      results: ManualSearchResult[]
      qualityScores?: QualityScoresMap
    }

    setResultsOnVm(vm, [
      {
        id: 'q1',
        title: 'Format Fallback Test',
        quality: 'FLAC',
        format: 'FLAC',
        downloadType: 'Torrent',
        resultUrl: 'https://indexer/info/4',
        source: 'test',
        size: 0,
      },
    ])

    await nextTick()

    const badge = wrapper.find('.col-quality .quality-badge')
    expect(badge.exists()).toBe(true)
    expect(badge.text()).toContain('FLAC')
    // Should not contain duplicate 'FLAC' after the dot
    expect(badge.text()).not.toContain('FLAC · FLAC')
  })

  it('shows rejection reason instead of score for rejected results', async () => {
    const wrapper = mount(ManualSearchModal, {
      props: { isOpen: true, audiobook: null },
      global: { stubs },
    })
    const vm = wrapper.vm as unknown as {
      results: ManualSearchResult[]
      qualityScores?: QualityScoresMap
    }

    const fake = {
      id: 'r3',
      title: 'Rejected Test',
      downloadType: 'Torrent',
      resultUrl: 'https://indexer/info/3',
      source: 'test',
      size: 0,
    }

    setResultsOnVm(vm, [fake])

    const scoreObj: QualityScore = {
      searchResult: fake,
      totalScore: -1,
      scoreBreakdown: {},
      rejectionReasons: ['No seeds'],
      isRejected: true,
    }

    // Try to set via .value (ref) when available
    if (
      vm.qualityScores &&
      (
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).value &&
      typeof (
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).value!.set === 'function'
    ) {
      ;(
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).value!.set('r3', scoreObj)
    }

    // Also set directly on the unwrapped proxy for compatibility with test runner behavior
    if (
      vm.qualityScores &&
      typeof (
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).set === 'function'
    ) {
      ;(
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).set!('r3', scoreObj)
    }

    await nextTick()

    const badge = wrapper.find('.col-score .score-badge.rejected')
    expect(badge.exists()).toBe(true)
    // Badge should read 'Rejected'
    expect(badge.text()).toContain('Rejected')
    // The title/hover should contain the rejection reason
    expect(badge.attributes('title')).toContain('No seeds')
  })

  it('shows Smart total as the score badge when smartScore is present', async () => {
    const wrapper = mount(ManualSearchModal, {
      props: { isOpen: true, audiobook: null },
      global: { stubs },
    })
    const vm = wrapper.vm as unknown as {
      results: ManualSearchResult[]
      qualityScores?: QualityScoresMap
    }

    setResultsOnVm(vm, [
      {
        id: 'r1',
        title: 'Smart Score Test',
        downloadType: 'Torrent',
        resultUrl: 'https://indexer/info/1',
        source: 'test',
        size: 0,
      },
    ])

    // Provide a quality score with a smartScore. Ensure both ref.value and unwrapped Map get the entry
    const scoreObj: QualityScore = {
      searchResult: vm.results[0],
      totalScore: 47,
      scoreBreakdown: { Quality: 65 },
      rejectionReasons: [],
      isRejected: false,
      smartScore: 12345,
      smartScoreBreakdown: { Quality: 65000 },
    }

    // Try to set via .value (ref) when available
    if (
      vm.qualityScores &&
      (
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).value &&
      typeof (
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).value!.set === 'function'
    ) {
      ;(
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).value!.set('r1', scoreObj)
    }

    // Also set directly on the unwrapped proxy for compatibility with test runner behavior
    if (
      vm.qualityScores &&
      typeof (
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).set === 'function'
    ) {
      ;(
        vm.qualityScores as unknown as {
          value?: Map<string, QualityScore>
          set?: (k: string, v: QualityScore) => void
        }
      ).set!('r1', scoreObj)
    }

    // As a last-resort replace the Map entirely
    // Provide smartScoreBreakdown so the visible total is computed from component averages
    scoreObj.smartScore = 1234.5
    scoreObj.smartScoreBreakdown = { Quality: 90000, Format: 8500, Seed: 2000 }
    vm.qualityScores = new Map([['r1', scoreObj]])

    await nextTick()

    const badge = wrapper.find('.col-score .score-badge')
    expect(badge.exists()).toBe(true)
    // Normalized components: Quality=90, Format=85, Seed=20 -> avg ~65
    expect(badge.text()).toContain('65')
  })
})

