// Defensive: JSDOM / Vitest may encounter `file://` asset URLs (e.g. transformed
// static asset paths like `file:///logo.svg`). Some environments propagate
// those to HTMLImageElement.src setters which can trigger Node internal URL/path
// handling and cause tests to crash. Normalize `file://` image URLs to plain
// absolute paths to avoid runtime errors during tests.
try {
  const imgProto = Object.getOwnPropertyDescriptor(HTMLImageElement.prototype, 'src')
  Object.defineProperty(HTMLImageElement.prototype, 'src', {
    set(this: HTMLImageElement, value: string) {
      try {
        if (typeof value === 'string' && value.startsWith('file:///')) {
          // Convert file URL (file:///logo.svg) to a usable pathname (/logo.svg)
          const u = new URL(value)
          return imgProto?.set?.call(this, u.pathname)
        }
      } catch {
        // fall through to default setter
      }
      return imgProto?.set?.call(this, value)
    },
    get(this: HTMLImageElement) {
      return imgProto?.get?.call(this)
    },
    configurable: true,
  })

  // Some code sets src via setAttribute('src', ...) which bypasses the property
  // setter. Intercept attribute assignments and normalize file:// URLs for src.
  const origSetAttr = Element.prototype.setAttribute
  Element.prototype.setAttribute = function (name: string, value: string) {
    try {
      if (
        typeof name === 'string' &&
        name.toLowerCase() === 'src' &&
        typeof value === 'string' &&
        value.startsWith('file:///')
      ) {
        const u = new URL(value)
        return origSetAttr.call(this, name, u.pathname)
      }
    } catch {}
    return origSetAttr.call(this, name, value)
  }
} catch {}

// Defensive: some test runners / source-map consumers may attempt to read 'file:///logo.svg'
  // which can throw on Windows / Node file APIs. Normalize any `file:///...` paths to an
  // absolute pathname or return an empty string so tests don't crash during stacktrace
  // or source-map processing.
  try {

    const _fs = require('fs') as typeof import('fs')
    const _origRead = _fs.readFile.bind(_fs)
    const _origReadSync = _fs.readFileSync.bind(_fs)
    const _origExistsSync = _fs.existsSync.bind(_fs)
    const _origStatSync = _fs.statSync.bind(_fs)
    const _origRealpathSync = _fs.realpathSync.bind(_fs)
    const _origCreateReadStream = _fs.createReadStream.bind(_fs)
    const _origOpenSync = _fs.openSync ? _fs.openSync.bind(_fs) : undefined
    const _origPromisesRead = _fs.promises && _fs.promises.readFile ? _fs.promises.readFile.bind(_fs.promises) : undefined

    function normalizePathArg(p: unknown) {
      try {
        if (typeof p === 'string' && p.startsWith('file:///')) {
          // Convert 'file:///logo.svg' -> '/logo.svg' (safe for test runtime)
          return new URL(p).pathname
        }
      } catch {}
      return p
    }

    function isProblematicLogoPath(p: unknown) {
      const np = typeof p === 'string' ? p : ''
      return np === 'file:///logo.svg' || np.endsWith('/logo.svg')
    }

    ;(_fs as unknown).readFile = function (p: unknown, ...args: unknown[]) {
      const path = normalizePathArg(p)
      if (isProblematicLogoPath(p)) {
        const cb = args[args.length - 1]
        if (typeof cb === 'function') return cb(null, '')
        return Promise.resolve('')
      }
      return _origRead(path, ...args)
    }

    ;(_fs as unknown).readFileSync = function (p: unknown, ...args: unknown[]) {
      const path = normalizePathArg(p)
      if (isProblematicLogoPath(p)) return ''
      return _origReadSync(path, ...args)
    }

    if (_origPromisesRead) {
      ;(_fs as unknown).promises.readFile = function (p: unknown, ...args: unknown[]) {
        const path = normalizePathArg(p)
        if (isProblematicLogoPath(p)) return Promise.resolve('')
        return _origPromisesRead(path, ...args)
      }
    }

    ;(_fs as unknown).existsSync = function (p: unknown) {
      const path = normalizePathArg(p)
      if (isProblematicLogoPath(p)) return true
      return _origExistsSync(path)
    }

    ;(_fs as unknown).statSync = function (p: unknown, ...args: unknown[]) {
      const path = normalizePathArg(p)
      if (isProblematicLogoPath(p)) return { isFile: () => true, isDirectory: () => false } as unknown
      return _origStatSync(path, ...args)
    }

    ;(_fs as unknown).realpathSync = function (p: unknown, ...args: unknown[]) {
      const path = normalizePathArg(p)
      if (isProblematicLogoPath(p)) return path
      return _origRealpathSync(path, ...args)
    }

    ;(_fs as unknown).createReadStream = function (p: unknown, ...args: unknown[]) {
      const path = normalizePathArg(p)
      if (isProblematicLogoPath(p)) return _origCreateReadStream('/dev/null')
      return _origCreateReadStream(path, ...args)
    }

    if (_origOpenSync) {
      ;(_fs as unknown).openSync = function (p: unknown, ...args: unknown[]) {
        const path = normalizePathArg(p)
        if (isProblematicLogoPath(p)) return _origOpenSync(path)
        return _origOpenSync(path, ...args)
      }
    }
  } catch {}

import { defineStore } from 'pinia'
import { ref, computed, shallowRef, triggerRef } from 'vue'
import type { Download, SearchResult, Audiobook } from '@/types'
import { apiService } from '@/services/api'
import { useLibraryStore } from '@/stores/library'
import { signalRService } from '@/services/signalr'
import { errorTracking } from '@/services/errorTracking'
import { logger } from '@/utils/logger'

export const useDownloadsStore = defineStore('downloads', () => {
  const downloads = shallowRef<Download[]>([])
  const isLoading = ref(false)
  let unsubscribeUpdate: (() => void) | null = null
  let unsubscribeList: (() => void) | null = null
  let unsubscribeQueue: (() => void) | null = null
  let unsubscribeAudiobook: (() => void) | null = null

  // Subscribe to SignalR updates
  const initializeSignalR = () => {
    // Subscribe to individual download updates
    unsubscribeUpdate = signalRService.onDownloadUpdate(async (updatedDownloads) => {
      updatedDownloads.forEach((updated) => {
        const index = downloads.value.findIndex((d) => d.id === updated.id)
        if (index !== -1) {
          // Update existing download
          downloads.value[index] = updated
        } else {
          // Add new download
          downloads.value.unshift(updated)
        }
      })
      triggerRef(downloads)

      // If any updated downloads are completed and linked to an audiobook, refresh that audiobook in the library store
      // Refresh linked audiobooks so UI shows newly-created files. Use Promise.all to avoid unbounded concurrency.
      const libraryStore = useLibraryStore()
      const tasks: Promise<void>[] = []
      for (const updated of updatedDownloads) {
        const status = (updated.status || '').toString().toLowerCase()
        if (
          (status === 'completed' || status === 'ready') &&
          typeof updated.audiobookId === 'number'
        ) {
          const aid = updated.audiobookId as number
          tasks.push(
            (async () => {
              try {
                const latest = await apiService.getAudiobook(aid)
                // Find existing index
                const idx = libraryStore.audiobooks.findIndex((b) => b.id === latest.id)
                if (idx !== -1) {
                  // Preserve the original object reference so components bound to it update reactively
                  const target = libraryStore.audiobooks[idx]!
                  Object.assign(target, latest)
                } else {
                  libraryStore.audiobooks.unshift(latest)
                }
              } catch (e) {
                logger.warn(
                  '[Downloads Store] Failed to refresh audiobook after download update',
                  e,
                )
              }
            })(),
          )
        }
      }
      if (tasks.length > 0) await Promise.all(tasks)

      // Sort by start date
      downloads.value.sort(
        (a, b) => new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime(),
      )
      triggerRef(downloads)
    })

    // Subscribe to full downloads list
    unsubscribeList = signalRService.onDownloadsList((downloadsList) => {
      downloads.value = downloadsList
      triggerRef(downloads)
    })

    // Subscribe to queue updates (replacement list from backend)
    unsubscribeQueue = signalRService.onQueueUpdate((queueItems) => {
      // QueueUpdate provides the current queue state
      // When a download is completed and removed, it won't be in this list
      // We need to update our downloads to match the queue
      const currentDownloadIds = new Set(downloads.value.map(d => d.id))
      const queueIds = new Set(queueItems.map(q => q.id))

      // Remove downloads that are no longer in the queue
      downloads.value = downloads.value.filter(d => queueIds.has(d.id))

      // Update existing and add new items from queue
      queueItems.forEach((queueItem) => {
        const existingIndex = downloads.value.findIndex(d => d.id === queueItem.id)

        // Map QueueItem to Download format
        const downloadItem: Download = {
          id: queueItem.id,
          title: queueItem.title || 'Unknown',
          artist: queueItem.author || '',
          album: queueItem.series || '',
          originalUrl: '',
          status: queueItem.status as unknown,
          progress: queueItem.progress || 0,
          totalSize: queueItem.size || 0,
          downloadedSize: queueItem.downloaded || 0,
          downloadPath: queueItem.remotePath || '',
          finalPath: queueItem.localPath || '',
          startedAt: queueItem.addedAt,
          completedAt: undefined,
          errorMessage: queueItem.errorMessage,
          downloadClientId: queueItem.downloadClientId,
          metadata: {},
        }

        if (existingIndex !== -1) {
          downloads.value[existingIndex] = downloadItem
        } else {
          downloads.value.push(downloadItem)
        }
      })

      triggerRef(downloads)
    })

    // Subscribe to AudiobookUpdate messages so we can apply updated audiobook (with Files)
    unsubscribeAudiobook = signalRService.onAudiobookUpdate((updatedAudiobook) => {
      try {
        const libraryStore = useLibraryStore()
        const idx = libraryStore.audiobooks.findIndex((b) => b.id === updatedAudiobook.id)
        if (idx !== -1) {
          const target = libraryStore.audiobooks[idx] as Audiobook
          Object.assign(target, updatedAudiobook)
        } else {
          libraryStore.audiobooks.unshift(updatedAudiobook)
        }
      } catch (e) {
        logger.warn('[Downloads Store] Failed to apply AudiobookUpdate', e)
      }
    })
    // audiobook unsubscribe will be cleaned up in the common cleanup below
  }

  // Initialize SignalR connection
  initializeSignalR()

  const activeDownloads = computed(() => {
    const active = downloads.value.filter((d) => {
      const status = (d.status || '').toString().toLowerCase()
      const isActive = ['queued', 'downloading', 'paused', 'processing'].includes(status)
      return isActive
    })
    return active
  })

  const completedDownloads = computed(() =>
    downloads.value.filter((d) => {
      const status = (d.status || '').toString().toLowerCase()
      return status === 'completed' || status === 'ready'
    }),
  )

  const failedDownloads = computed(() =>
    downloads.value.filter((d) => (d.status || '').toString().toLowerCase() === 'failed'),
  )

  const loadDownloads = async () => {
    isLoading.value = true
    try {
      const downloadList = await apiService.getDownloads()
      downloads.value = downloadList
      triggerRef(downloads)
    } catch (error) {
      errorTracking.captureException(error as Error, {
        component: 'DownloadsStore',
        operation: 'loadDownloads',
      })
    } finally {
      isLoading.value = false
    }
  }

  const startDownload = async (searchResult: SearchResult, downloadClientId: string) => {
    try {
      const downloadId = await apiService.startDownload(searchResult, downloadClientId)
      // No need to manually refresh - SignalR will push the update
      return downloadId
    } catch (error) {
      errorTracking.captureException(error as Error, {
        component: 'DownloadsStore',
        operation: 'startDownload',
        metadata: { title: searchResult.title, downloadClientId },
      })
      throw error
    }
  }

  const cancelDownload = async (downloadId: string) => {
    try {
      await apiService.cancelDownload(downloadId)
      // No need to manually refresh - SignalR will push the update
    } catch (error) {
      errorTracking.captureException(error as Error, {
        component: 'DownloadsStore',
        operation: 'cancelDownload',
        metadata: { downloadId },
      })
      throw error
    }
  }

  const updateDownload = (updatedDownload: Download) => {
    const index = downloads.value.findIndex((d) => d.id === updatedDownload.id)
    if (index !== -1) {
      downloads.value[index] = updatedDownload
    }
  }

  // Cleanup on store destruction
  const cleanup = () => {
    if (unsubscribeUpdate) unsubscribeUpdate()
    if (unsubscribeList) unsubscribeList()
    if (unsubscribeQueue) unsubscribeQueue()
    if (unsubscribeAudiobook) unsubscribeAudiobook()
  }

  return {
    downloads,
    isLoading,
    activeDownloads,
    completedDownloads,
    failedDownloads,
    loadDownloads,
    startDownload,
    cancelDownload,
    updateDownload,
    cleanup,
  }
})

/**
 * Small path utility helpers used across UI components.
 * Keep these functions small and dependency-free so they are easy to reason about
 * and simple to unit test if needed.
 */

export function toForward(s: string | null | undefined): string {
  return (s || '').replace(/\\/g, '/')
}

export function trimTrailingSlash(s: string): string {
  let out = s
  while (out.endsWith('/') || out.endsWith('\\')) out = out.slice(0, -1)
  return out
}

export function normalizeForCompare(s: string | null | undefined): string {
  return toForward(trimTrailingSlash(s || '')).toLowerCase()
}

export function isAbsolutePath(s: string): boolean {
  return /^([a-zA-Z]:[\\/]|[\\/])/.test(s)
}

/**
 * If `value` contains the configured `root` prefix, remove it and return the
 * relative portion (respecting backslash style). Returns null if no match.
 */
export function stripRootPrefix(root: string, value: string): string | null {
  if (!root || !value) return null
  try {
    const nroot = toForward(root).toLowerCase()
    const nval = toForward(value).toLowerCase()

    if (nval.includes(nroot)) {
      const idx = nval.indexOf(nroot)
      const rel = toForward(value).slice(idx + nroot.length).replace(/^\/+/, '')
      const useBackslash = root.includes('\\')
      return useBackslash ? rel.replace(/\//g, '\\') : rel
    }

    // fallback: try matching two-segment windows from the end toward the start
    const segs = nroot.split('/')
    for (let i = Math.max(0, segs.length - 2); i >= 0; i--) {
      const two = segs.slice(i, i + 2).join('/')
      if (two && nval.includes(two)) {
        const idx = nval.indexOf(two)
        const rel = toForward(value).slice(idx + two.length).replace(/^\/+/, '')
        const useBackslash = root.includes('\\')
        return useBackslash ? rel.replace(/\//g, '\\\\') : rel
      }
    }
  } catch (err) {
    // noop — fall through to null
  }

  return null
}

export function joinPaths(root: string | null | undefined, relative: string | null | undefined): string {
  if (!root) return relative || ''
  const useBackslash = (root || '').includes('\\')
  const r = trimTrailingSlash(toForward(root || ''))
  const rel = (relative || '').toString().replace(/^\/+/, '')
  const combined = rel ? `${r}/${rel}` : r
  return useBackslash ? combined.replace(/\//g, '\\') : combined
}

